const normalizeHeading = (heading) => {
  if (typeof heading !== "number" || Number.isNaN(heading)) {
    return null;
  }

  const wrapped = ((heading % 360) + 360) % 360;
  return {
    raw: wrapped,
    compass: (360 - wrapped + 360) % 360
  };
};

const handleOrientation = (event) => {
  const heading = typeof event.webkitCompassHeading === "number"
    ? event.webkitCompassHeading
    : typeof event.alpha === "number"
      ? event.alpha
      : null;

  const result = normalizeHeading(heading);
  if (!result) {
    return;
  }

  compassVar.setNumber(result.compass);
  nakedVar.setNumber(result.raw);
};

const registrationKey = "__compassOrientationRegistration__";
if (!window.DeviceOrientationEvent) {
  messageVar.setString("Device orientation unsupported");
  compassVar.setNumber(400);
  nakedVar.setNumber(0);
  return;
}

const useAbsolute = "ondeviceorientationabsolute" in window;
messageVar.setString(useAbsolute ? "Absolute orientation" : "Relative orientation");

const eventName = useAbsolute ? "deviceorientationabsolute" : "deviceorientation";
const useCapture = useAbsolute;

const previousRegistration = window[registrationKey];
if (previousRegistration) {
  window.removeEventListener(
    previousRegistration.eventName,
    previousRegistration.handler,
    previousRegistration.useCapture
  );
}

const registration = {
  eventName,
  handler: handleOrientation,
  useCapture
};

window[registrationKey] = registration;
window.addEventListener(eventName, handleOrientation, useCapture);
